static void dfs(int **image, int rows, int cols, int r, int c, int oldColor, int newColor) {
  if (r < 0 || r >= rows || c < 0 || c >= cols || image[r][c] != oldColor) return;
  image[r][c] = newColor;
  dfs(image, rows, cols, r + 1, c, oldColor, newColor);
  dfs(image, rows, cols, r - 1, c, oldColor, newColor);
  dfs(image, rows, cols, r, c + 1, oldColor, newColor);
  dfs(image, rows, cols, r, c - 1, oldColor, newColor);
}

int **floodFill(int **image, int imageSize, int *imageColSize, int sr, int sc, int newColor, int *returnSize, int **returnColumnSizes) {
  int oldColor = image[sr][sc];
  if (oldColor != newColor) dfs(image, imageSize, imageColSize[0], sr, sc, oldColor, newColor);
  *returnSize = imageSize;
  *returnColumnSizes = (int *)malloc(sizeof(int) * imageSize);
  for (int i = 0; i < imageSize; i++) (*returnColumnSizes)[i] = imageColSize[i];
  return image;
}

class Solution {
  void dfs(vector<vector<int>> &image, int r, int c, int oldColor, int newColor) {
    if (r < 0 || r >= (int)image.size() || c < 0 || c >= (int)image[0].size() || image[r][c] != oldColor) return;
    image[r][c] = newColor;
    dfs(image, r + 1, c, oldColor, newColor);
    dfs(image, r - 1, c, oldColor, newColor);
    dfs(image, r, c + 1, oldColor, newColor);
    dfs(image, r, c - 1, oldColor, newColor);
  }

public:
  vector<vector<int>> floodFill(vector<vector<int>> &image, int sr, int sc, int newColor) {
    int oldColor = image[sr][sc];
    if (oldColor != newColor) dfs(image, sr, sc, oldColor, newColor);
    return image;
  }
};

func floodFill(image [][]int, sr int, sc int, newColor int) [][]int {
	oldColor := image[sr][sc]
	if oldColor == newColor {
		return image
	}
	rows, cols := len(image), len(image[0])
	var dfs func(r, c int)
	dfs = func(r, c int) {
		if r < 0 || r >= rows || c < 0 || c >= cols || image[r][c] != oldColor {
			return
		}
		image[r][c] = newColor
		dfs(r+1, c)
		dfs(r-1, c)
		dfs(r, c+1)
		dfs(r, c-1)
	}
	dfs(sr, sc)
	return image
}

class Solution {
  private void dfs(int[][] image, int r, int c, int oldColor, int newColor) {
    if (r < 0 || r >= image.length || c < 0 || c >= image[0].length || image[r][c] != oldColor) return;
    image[r][c] = newColor;
    dfs(image, r + 1, c, oldColor, newColor);
    dfs(image, r - 1, c, oldColor, newColor);
    dfs(image, r, c + 1, oldColor, newColor);
    dfs(image, r, c - 1, oldColor, newColor);
  }

  public int[][] floodFill(int[][] image, int sr, int sc, int newColor) {
    int oldColor = image[sr][sc];
    if (oldColor != newColor) dfs(image, sr, sc, oldColor, newColor);
    return image;
  }
}

class Solution:
    def floodFill(self, image: List[List[int]], sr: int, sc: int, newColor: int) -> List[List[int]]:
        old_color = image[sr][sc]
        if old_color == newColor:
            return image
        rows, cols = len(image), len(image[0])

        def dfs(r: int, c: int):
            if r < 0 or r >= rows or c < 0 or c >= cols or image[r][c] != old_color:
                return
            image[r][c] = newColor
            dfs(r + 1, c)
            dfs(r - 1, c)
            dfs(r, c + 1)
            dfs(r, c - 1)

        dfs(sr, sc)
        return image

impl Solution {
  pub fn flood_fill(image: &mut Vec<Vec<i32>>, sr: i32, sc: i32, new_color: i32) {
    let old_color = image[sr as usize][sc as usize];
    if old_color == new_color {
      return;
    }
    let rows = image.len() as i32;
    let cols = image[0].len() as i32;
    fn dfs(image: &mut Vec<Vec<i32>>, r: i32, c: i32, old_color: i32, new_color: i32, rows: i32, cols: i32) {
      if r < 0 || r >= rows || c < 0 || c >= cols || image[r as usize][c as usize] != old_color {
        return;
      }
      image[r as usize][c as usize] = new_color;
      dfs(image, r + 1, c, old_color, new_color, rows, cols);
      dfs(image, r - 1, c, old_color, new_color, rows, cols);
      dfs(image, r, c + 1, old_color, new_color, rows, cols);
      dfs(image, r, c - 1, old_color, new_color, rows, cols);
    }
    dfs(image, sr, sc, old_color, new_color, rows, cols);
  }
}

const floodFill = (image: number[][], sr: number, sc: number, newColor: number): number[][] => {
  const oldColor = image[sr][sc];
  if (oldColor === newColor) return image;
  const rows = image.length;
  const cols = image[0].length;
  const dfs = (r: number, c: number) => {
    if (r < 0 || r >= rows || c < 0 || c >= cols || image[r][c] !== oldColor) return;
    image[r][c] = newColor;
    dfs(r + 1, c);
    dfs(r - 1, c);
    dfs(r, c + 1);
    dfs(r, c - 1);
  };
  dfs(sr, sc);
  return image;
};
